# Simple CYK parser to verify membership
def parse_cyk(tokens, rules):
    n = len(tokens)
    # rules: list of (lhs, rhs) where rhs is a tuple of symbols
    # terminals are quoted strings like 'scene', 'interview', '['

    # Build lookup for terminal rules
    term_rules = {}  # terminal -> list of nonterminals that produce it
    nonterm_rules = {}  # (A, B) -> list of C where C -> A B

    for lhs, rhs in rules:
        if len(rhs) == 1 and rhs[0].startswith("'") and rhs[0].endswith("'"):
            t = rhs[0].strip("'")
            if t not in term_rules:
                term_rules[t] = []
            term_rules[t].append(lhs)
        elif len(rhs) == 2:
            key = (rhs[0], rhs[1])
            if key not in nonterm_rules:
                nonterm_rules[key] = []
            nonterm_rules[key].append(lhs)

    # CYK table
    table = [[set() for _ in range(n)] for _ in range(n)]

    # Fill diagonal (length 1)
    for i in range(n):
        t = tokens[i]
        if t in term_rules:
            for nt in term_rules[t]:
                table[i][i].add(nt)

    # Fill rest
    for length in range(2, n+1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                for A, B in nonterm_rules:
                    if A in table[i][k] and B in table[k+1][j]:
                        for C in nonterm_rules[(A, B)]:
                            table[i][j].add(C)

    return 'S' in table[0][n-1]

