def can_derive(nonterm, tokens):
    """Check if nonterm can derive the given token list"""
    if nonterm == 'S':
        # S -> A or S -> A 'interview'
        if can_derive('A', tokens):
            return True
        if len(tokens) >= 1 and tokens[-1] == 'interview':
            if can_derive('A', tokens[:-1]):
                return True
        return False
