        return can_derive('B', tokens)
    elif nonterm == 'B':
        # B -> C D or B -> C
        if can_derive('C', tokens):
            return True
        for i in range(1, len(tokens)):
            if can_derive('C', tokens[:i]) and can_derive('D', tokens[i:]):
                return True
        return False
    elif nonterm == 'C':
        return can_derive('D', tokens)
    elif nonterm == 'D':
        # D -> '[' D ']' or D -> E
        if can_derive('E', tokens):
            return True
        if len(tokens) >= 3 and tokens[0] == '[' and tokens[-1] == ']':
            if can_derive('D', tokens[1:-1]):
                return True
        return False
    elif nonterm == 'E':
        # E -> F or E -> 'interview' F
        if can_derive('F', tokens):
            return True
